with joined as (select e.station,e.hour_code,e.entries,x.exits from {{ ref('stg_entries') }} e inner join {{ ref('stg_exits') }} x on e.station=x.station and e.hour_code=x.hour_code), ordered as (select *, case hour_code when 'H05' then 1 when 'H06' then 2 when 'H07' then 3 when 'H08' then 4 when 'H09' then 5 when 'H10' then 6 when 'H11' then 7 when 'H12' then 8 when 'H13' then 9 when 'H14' then 10 when 'H15' then 11 when 'H16' then 12 when 'H17' then 13 when 'H18' then 14 when 'H19' then 15 when 'H20' then 16 when 'H21' then 17 when 'H22' then 18 when 'H23' then 19 when 'H00' then 20 when 'H01' then 21 end as hour_order, case when hour_code in ('H05','H06') then 'early' when hour_code in ('H07','H08','H09') then 'am_peak' when hour_code in ('H10','H11','H12','H13','H14','H15') then 'interpeak' when hour_code in ('H16','H17','H18') then 'pm_peak' when hour_code in ('H19','H20','H21') then 'evening' else 'late' end as time_band from joined) select station || '|' || hour_code as station_hour_key, station, hour_code, hour_order, time_band, entries, exits, entries+exits as total_flow, exits-entries as net_arrivals from ordered
